* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #172b36; color: #f3f4e9; }
body { min-height: 100vh; margin: 0; display: grid; place-items: center; padding: 24px 16px; background: radial-gradient(ellipse at 50% 0%, #294450 0%, #172b36 65%); }
.meter-card { width: min(100%, 460px); padding: 30px; border: 1px solid #45616a; border-radius: 20px; background: #203741; box-shadow: 0 24px 70px #0c1a20a8; }
.meter-header { display: flex; align-items: center; gap: 14px; }
.taxi-icon { width: 46px; height: 46px; display: grid; place-items: center; border-radius: 13px; background: #f2c75c; color: #203741; font-size: 26px; transform: rotate(180deg); }
.eyebrow, .stat-label { margin: 0; color: #a9c0bd; font-size: 13px; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 3px 0 0; font-size: clamp(20px, 5vw, 25px); line-height: 1.2; letter-spacing: -.03em; }
.live-dot { width: 10px; height: 10px; margin-left: auto; border-radius: 50%; background: #8bd3a2; box-shadow: 0 0 0 5px #8bd3a21c; }
.fare-panel { margin: 28px 0 22px; padding: 24px; border: 1px solid #3c5961; border-radius: 15px; background: #182e37; text-align: center; }
.fare { margin: 4px 0 0; color: #f2c75c; font-size: clamp(48px, 13vw, 64px); font-weight: 800; letter-spacing: -.055em; line-height: 1.05; font-variant-numeric: tabular-nums; }
.fare-note { margin: 8px 0 0; color: #a9c0bd; font-size: 15px; }
.trip-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.stat { min-width: 0; display: flex; align-items: center; gap: 12px; padding: 16px 13px; border: 1px solid #45616a; border-radius: 13px; background: #29434c; }
.stat-icon { width: 36px; height: 36px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 10px; background: #f2c75c; color: #203741; font-size: 22px; font-weight: 800; }
.wait-icon { background: #8bd3a2; }
.stat-label { font-size: 11px; }
.stat-value { margin: 4px 0 0; font-size: clamp(20px, 5vw, 25px); font-weight: 750; font-variant-numeric: tabular-nums; white-space: nowrap; }
.unit { color: #b8cdca; font-size: 15px; font-weight: 550; }
.controls { display: grid; gap: 11px; margin-top: 22px; }
button { min-height: 56px; border: 0; border-radius: 12px; font: inherit; font-size: 16px; cursor: pointer; transition: transform .12s ease, background-color .12s ease, box-shadow .12s ease; }
.add-button { display: flex; align-items: center; gap: 13px; padding: 10px 15px; background: #f2c75c; color: #203741; text-align: left; }
.add-button:hover { background: #ffda75; }
.add-button strong, .add-button small { display: block; }
.add-button strong { font-size: 16px; }
.add-button small { margin-top: 2px; color: #42524a; font-size: 13px; }
.button-plus { width: 32px; height: 32px; display: grid; place-items: center; border-radius: 9px; background: #2037411c; font-size: 23px; font-weight: 500; }
.reset-button { width: 100%; margin-top: 13px; border: 1px solid #58717a; background: transparent; color: #f3f4e9; }
.reset-button:hover { background: #2c4751; }
button:focus-visible { outline: 3px solid #8bd3a2; outline-offset: 3px; }
button:active { transform: translateY(2px) scale(.99); }
footer { margin-top: 22px; color: #a9c0bd; font-size: 11px; font-weight: 700; letter-spacing: .09em; text-align: center; }
footer span { padding: 0 5px; color: #f2c75c; }
@media (max-width: 390px) { .meter-card { padding: 23px 18px; } .stat { gap: 8px; padding: 13px 9px; } .stat-icon { width: 32px; height: 32px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition-duration: .01ms !important; } }

const distanceDisplay = document.querySelector('#distance');
const waitingDisplay = document.querySelector('#waiting');
const fareDisplay = document.querySelector('#fare');

let kilometers = 0;
let minutes = 0;

function render() {
  distanceDisplay.textContent = kilometers.toFixed(2);
  waitingDisplay.textContent = String(minutes);
  fareDisplay.textContent = `$${(3 + kilometers * 1.5 + minutes * 0.4).toFixed(2)}`;
}

document.querySelector('#add-km').addEventListener('click', () => {
  kilometers += 1;
  render();
});

document.querySelector('#add-minute').addEventListener('click', () => {
  minutes += 1;
  render();
});

document.querySelector('#new-trip').addEventListener('click', () => {
  kilometers = 0;
  minutes = 0;
  render();
});
